/** Characterization only: independent explicit unary interpretations, NOT production model admission. */
final class ContextSignedEligibilityMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 static Snapshot bind(boolean x,String s)throws Exception{return ContextSignedWitnessNativeMatrix.bind(x,s);}
 static Runnable work(){return ContextGroundProductionRounds.budget(WORK);}
 static ContextSignedWitnessNativeBranch.Receipt nativeBranch(Snapshot x,List<Snapshot> fs,boolean refuted){ContextSignedWitnessNativeBranch.Policy p=ContextSignedWitnessNativeMatrix.policy();ContextSignedWitnessNativeBranch.Result r=ContextSignedWitnessNativeBranch.run(x,fs,p);require(r.status==(refuted?ContextSignedWitnessNativeBranch.Status.REFUTED:ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED),r.phase+": "+r.reason);ContextSignedWitnessNativeBranch.Receipt receipt=refuted?r.rejection:r.output;ContextSignedWitnessNativeBranchAudit.check(receipt,x,fs,p,WORK,1);require(true,"fresh actual complete signed branch audit, not assumed language readiness");return receipt;}
 interface Attempt{void run()throws Exception;}
 static void rejects(Attempt a,String message)throws Exception{String found=null;try{a.run();}catch(Exception e){found=e.getMessage();}require(found!=null&&found.contains(message),"exact independent gate: "+message+", actual="+found);}
 static void barriers()throws Exception{
  Snapshot x=bind(true,"!anchor(1); !@u seed(u)->ready(u);"),positive=bind(false,"!$u seed(u)&&blocked(u);"),negative=bind(false,"!$u seed(u)&&~blocked(u);");
  ContextProductionFamilyAssembly.Result yes=ContextProductionFamilyAssembly.assemble(x,Collections.singletonList(positive),WORK);require(yes.assembled,yes.reason);ContextProductionFamilyAssembly.Evaluation closed=yes.artifact.evaluate(8,16,WORK,500000);require(closed.status==ContextProductionFamilyAssembly.Status.FIXED_POINT,closed.reason);require(yes.artifact.rows.size()==3&&yes.artifact.rows.stream().anyMatch(v->v.source.equals(positive.primary.get(0).source)&&v.seedLiterals==2),"complete whole positive-bundle baseline");
  ContextProductionFamilyAssembly.Result no=ContextProductionFamilyAssembly.assemble(x,Collections.singletonList(negative),WORK);require(!no.assembled&&no.artifact==null&&no.reason.equals("Positive private witness bundle required"),"FIRST current family assembly private-sign gate, before family closure/model");require(new Model(value(1)).predicate("anchor",true,false).predicate("seed",true,false).predicate("ready",true,false).predicate("blocked",false,false).witness(negative.primary.get(0).source,0).holds(Arrays.asList(x,negative)),"explicit ALL-domain model for the SAME private-sign rejected request");nativeBranch(x,Collections.singletonList(negative),false);
  Packet common=ContextWitnessResultTransport.primarySeeds(x,WORK).packet;rejects(()->ContextWitnessResultTransport.privatePoolSigned(common,x,negative,WORK),"Positive private witness bundle required");
  Snapshot signedX=bind(true,"!$u seed(u)&&~blocked(u);"),foreign=bind(false,"!p(1);");ContextProductionFamilyAssembly.Result commonNo=ContextProductionFamilyAssembly.assemble(signedX,Collections.singletonList(foreign),WORK);require(!commonNo.assembled&&commonNo.artifact==null&&commonNo.reason.equals("Positive common witness pool required"),"separate COMMON sign gate before old private seed construction");
  ContextProductionFamilyAssembly.Result isolated=ContextProductionFamilyAssembly.assemble(signedX,Collections.emptyList(),WORK);require(isolated.assembled,"no foreign pool: signed common materialization itself accepted");ContextProductionFamilyAssembly.Evaluation stopped=isolated.artifact.evaluate(8,16,WORK,500000);require(stopped.status==ContextProductionFamilyAssembly.Status.INCOMPLETE&&stopped.reason.equals("Positive Horn closure pool required"),"removing private branch does NOT remove independent Horn-pool gate");require(new Model(value(1)).predicate("seed",true,false).predicate("blocked",false,false).witness(signedX.primary.get(0).source,0).holds(Collections.singletonList(signedX)),"explicit all-domain interpretation of SAME common-sign rejected request");nativeBranch(signedX,Collections.emptyList(),false);
  System.out.println("SIGNED_ELIGIBILITY_BARRIERS positiveWitnessBaseline=true privateSignThenCommonSignThenHornPoolDistinct=true currentNativeBranchAudited=true productionGuardsUnchanged=true");
 }
 static void coverage()throws Exception{Snapshot x=bind(true,"!anchor(1); !@u absent(u)->~anchor(u);"),a=bind(false,"!$u seed(u);");ContextProductionFamilyAssembly.Result assembled=ContextProductionFamilyAssembly.assemble(x,Collections.singletonList(a),WORK);require(assembled.assembled,assembled.reason);ContextProductionFamilyAssembly.Evaluation old=assembled.artifact.evaluate(8,16,WORK,500000);require(old.status==ContextProductionFamilyAssembly.Status.INCOMPLETE&&old.reason.equals("No supported self-X producer snapshot; full-cut coverage remains incomplete"),"independent headless self-X coverage gap after successful positive-pool assembly");Source constraint=x.primary.get(1).source;require(old.qualification.uncovered.equals(Collections.singleton(constraint))&&old.qualification.fixedPoint==null&&old.refutations.isEmpty(),"exact ORIGINAL uncovered self constraint, no fabricated collision or closed family");require(x.primary.get(1).clauses.size()==1&&x.primary.get(1).clauses.get(0).literals.stream().noneMatch(t->t.positive),"negative head is a headless clause, never a dropped positive producer");require(new Model(value(1)).predicate("anchor",true,false).predicate("absent",false,false).predicate("seed",true,false).witness(a.primary.get(0).source,0).holds(Arrays.asList(x,a)),"explicit all-domain model checks SAME uncovered headless self constraint");nativeBranch(x,Collections.singletonList(a),false);
  Snapshot positive=bind(true,"!anchor(1); !@u seed(u)->ready(u);");ContextProductionFamilyAssembly.Result supported=ContextProductionFamilyAssembly.assemble(positive,Collections.singletonList(a),WORK);require(supported.assembled,supported.reason);require(supported.artifact.evaluate(8,16,WORK,500000).status==ContextProductionFamilyAssembly.Status.FIXED_POINT,"same witness topology with supported positive self producer qualifies");Snapshot clashing=bind(false,"!$u seed(u); !absent(1);");ContextProductionFamilyAssembly.Result collision=ContextProductionFamilyAssembly.assemble(x,Collections.singletonList(clashing),WORK);require(collision.assembled,collision.reason);ContextProductionFamilyAssembly.Evaluation rejected=collision.artifact.evaluate(8,16,WORK,500000);require(rejected.status==ContextProductionFamilyAssembly.Status.COLLISION&&!rejected.refutations.isEmpty()&&rejected.qualification.uncovered.contains(constraint),"direct negative proof can refute headless constraint while positive producer coverage stays incomplete");nativeBranch(x,Collections.singletonList(clashing),true);System.out.println("SIGNED_ELIGIBILITY_COVERAGE exactUncoveredOriginalSelfConstraint=true negativeHeadNotPositiveProducer=true noGuardDeletion=true");}
 static SemanticTermSnapshot value(int n)throws Exception{return bind(true,"!anchor("+n+");").primary.get(0).clauses.get(0).literals.get(0).arguments.get(0).value;}
 /** Exact all-admissible-value interpretation for THIS unary, one-variable, no-function profile.
  * Every named value has explicit truth; ALL OTHER admissible values share predicate defaults.
  * No enumeration of existing DB values is presented as universal quantification. */
 static final class Model {
  final List<SemanticTermSnapshot> points;final Map<String,boolean[]> truth=new HashMap<>();final Map<Source,Integer> witnesses=new HashMap<>();
  Model(SemanticTermSnapshot... points){this.points=Arrays.asList(points);for(int i=0;i<points.length;i++)for(int j=0;j<i;j++)require(!points[i].semanticallyEquals(points[j]),"distinct ordinary named values, not Origin inequality");}
  Model predicate(String p,boolean... values){if(values.length!=points.size()+1)throw new IllegalArgumentException("Named points plus outside-class truth required");truth.put(p,values);return this;}
  Model witness(Source s,int point){if(point<0||point>=points.size())throw new IllegalArgumentException("Concrete existential assignment required");witnesses.put(s,point);return this;}
  int fixed(SemanticTermSnapshot v){for(int n=0;n<points.size();n++)if(points.get(n).semanticallyEquals(v))return n;throw new IllegalArgumentException("Every original constant must be named in interpretation");}
  void atom(String p,int arity){if(!new HashSet<>(Arrays.asList("anchor","p","q","seed","blocked","absent","ready")).contains(p)||arity!=1||!truth.containsKey(p))throw new IllegalArgumentException("Explicit uninterpreted unary predicate profile required");}
  boolean literal(String p,boolean positive,int v){return truth.get(p)[v]==positive;}
  boolean holds(List<Snapshot> snapshots){
   // WHOLE shape/source preflight before considering truth, including every later row.
   Set<UUID> ids=new HashSet<>();int total=0;for(Snapshot s:snapshots){if(s.trustedGroup!=null)throw new IllegalArgumentException("Pass physical formulas for this interpretation check");ContextProductionFamilyAssembly.identity(s,s.inventory.localX,work());ContextProductionFamilyAssembly.claimContexts(s,ids,work());for(ContextProductionNativeBinding.Entry e:s.primary){if(++total>64)throw new IllegalArgumentException("Bounded whole interpretation required");if(e.bundle!=null){if(e.bundle.witnesses!=1||!witnesses.containsKey(e.source))throw new IllegalArgumentException("One concrete Source-owned existential assignment required");for(ContextWitnessBundle.Atom a:e.bundle.atoms){atom(a.predicate,a.arguments.size());ContextWitnessBundle.Slot t=a.arguments.get(0);if(t.witness>=0&&t.witness!=0)throw new IllegalArgumentException("Unsupported binder");if(t.witness<0)fixed(t.value);}}else for(Clause c:e.clauses){if(c.variables.size()>1)throw new IllegalArgumentException("At most one universal variable required");for(ContextProductionCapture.Atom a:c.literals){atom(a.predicate,a.arguments.size());ContextProductionCapture.Slot t=a.arguments.get(0);if(t.variable<0)fixed(t.value);}}}}
   for(Snapshot s:snapshots)for(ContextProductionNativeBinding.Entry e:s.primary){if(e.bundle!=null){for(ContextWitnessBundle.Atom a:e.bundle.atoms){ContextWitnessBundle.Slot t=a.arguments.get(0);if(!literal(a.predicate,a.positive,t.witness>=0?witnesses.get(e.source):fixed(t.value)))return false;}}else for(Clause c:e.clauses){int count=c.variables.isEmpty()?1:points.size()+1;for(int v=0;v<count;v++){boolean satisfied=false;for(ContextProductionCapture.Atom a:c.literals){ContextProductionCapture.Slot t=a.arguments.get(0);satisfied|=literal(a.predicate,a.positive,t.variable>=0?v:fixed(t.value));}if(!satisfied)return false;}}}return true;
  }
 }
 static void models()throws Exception{SemanticTermSnapshot one=value(1),two=value(2);Snapshot x=bind(true,"!anchor(1); !@u p(u)->q(u);"),split=bind(false,"!$u p(u); !$u ~q(u);"),joint=bind(false,"!$u p(u)&&~q(u);");Model m=new Model(one,two).predicate("anchor",true,false,false).predicate("p",true,false,false).predicate("q",true,false,false).witness(split.primary.get(0).source,0).witness(split.primary.get(1).source,1);require(m.holds(Arrays.asList(x,split)),"concrete ALL-domain interpretation of split existential occurrences; all outside predicates false");nativeBranch(x,Collections.singletonList(split),false);m.witness(joint.primary.get(0).source,0);require(!m.holds(Arrays.asList(x,joint)),"same proposed interpretation violates correlated original bundle");ContextSignedWitnessNativeBranch.Receipt contradiction=nativeBranch(x,Collections.singletonList(joint),true);require(contradiction.initialRejection!=null&&contradiction.initialRejection.checks.values().stream().flatMap(v->v.emptyProofs.stream()).anyMatch(v->v.support.sources.equals(new HashSet<>(Arrays.asList(x.primary.get(1).source,joint.primary.get(0).source)))),"actual two-Source proof, not failed model candidate, establishes joint inconsistency");
  Snapshot noRule=bind(true,"!anchor(1);"),coincident=bind(false,"!$u p(u); !$u q(u);");Model same=new Model(one).predicate("anchor",true,false).predicate("p",true,false).predicate("q",true,false).witness(coincident.primary.get(0).source,0).witness(coincident.primary.get(1).source,0);require(same.holds(Arrays.asList(noRule,coincident)),"distinct proof Origins CAN denote same concrete value; no disequality assumption");
  Snapshot a=bind(false,"!p(1);"),b=bind(false,"!~p(1);");Model yes=new Model(one).predicate("anchor",true,false).predicate("p",true,false),no=new Model(one).predicate("anchor",true,false).predicate("p",false,false);require(yes.holds(Arrays.asList(noRule,a))&&no.holds(Arrays.asList(noRule,b)),"independent A-X and B-X have separate interpretations");require(!yes.holds(Arrays.asList(noRule,a,b))&&!no.holds(Arrays.asList(noRule,a,b)),"neither per-cut model may be claimed as a model of communalized A+B");nativeBranch(noRule,Arrays.asList(a,b),false);nativeBranch(noRule,Collections.singletonList(ContextProductionNativeBinding.trusted("models",Arrays.asList(a,b),WORK)),true);
  Snapshot universal=bind(true,"!@u p(u);");require(!new Model(one).predicate("p",true,false).holds(Collections.singletonList(universal)),"p(1) alone does not satisfy @u p(u): unmentioned admissible values matter");require(new Model(one).predicate("p",true,true).holds(Collections.singletonList(universal)),"all-admissible extension with true outside-class satisfies universal");Snapshot bad=bind(false,"!@u p(u,u);");rejects(()->new Model(one).predicate("anchor",false,false).predicate("p",true,true).holds(Arrays.asList(noRule,bad)),"uninterpreted unary predicate profile");System.out.println("SIGNED_ELIGIBILITY_MODELS correlatedWholeBundle=true originsNotInequality=true independentPerCutModels=true allAdmissibleOutsideClass=true testOnlyUnaryProfile=true noProductionModelCapability=true");}
}
